<?php
declare(strict_types=1);
namespace Architex\Tests\Integration\Http;
use Architex\Http\AuthenticationKernelFactory;use Architex\Http\Request;use Architex\Platform\Identity\Identifier;use Architex\Platform\Identity\PasswordResetNotifier;use Architex\Platform\Identity\RegistrationNotifier;use Architex\Platform\Identity\SessionService;use Architex\Tests\Support\MariaDbTestCase;
final class SurveyJobHttpTest extends MariaDbTestCase
{
 public function testAuthenticatedSurveyWorkflowPersistsAndExports():void{[$o,$u,$p]=$this->seed();$n=new class implements RegistrationNotifier,PasswordResetNotifier{public function isAvailable():bool{return false;}public function send(string$email,string$token,string$expiresAt):void{}};$k=(new AuthenticationKernelFactory($this->pdo,$n,$n))->create();$session=(new SessionService($this->pdo))->rotate($u);$h=['Cookie'=>'architex_session='.$session->token,'X-Organisation-Id'=>$o,'X-CSRF-Token'=>$session->csrfToken];$payload=['jobNumber'=>'SUR-HTTP-01','surveyType'=>'topographical','title'=>'HTTP topographical survey','responsibleRole'=>'land_surveyor','coordinateReferenceSystem'=>'Hartebeesthoek94 / Lo29','verticalDatum'=>'MSL','sourceBasis'=>[['title'=>'Geomatics Profession Act','url'=>'https://www.gov.za/documents/geomatics-profession-act','retrievedAt'=>'2026-08-28']]];$blocked=$h;unset($blocked['X-CSRF-Token']);self::assertSame(419,$k->handle($this->json('POST',"/api/v1/projects/$p/survey-jobs",$blocked,$payload))->status());$created=$k->handle($this->json('POST',"/api/v1/projects/$p/survey-jobs",$h,$payload));self::assertSame(201,$created->status(),$created->body());$id=$created->json()['data']['id'];foreach([['CP01','1000.1','2000.2','125.4'],['CP02','1100.5','2100.7','126.0']]as$i=>$point){$res=$k->handle($this->json('POST',"/api/v1/survey-jobs/$id/observations",$h,['expectedVersion'=>$i+1,'pointCode'=>$point[0],'observationType'=>'control_point','easting'=>$point[1],'northing'=>$point[2],'elevation'=>$point[3],'status'=>'verified','sourceReference'=>'FIELD-HTTP','sourceUrl'=>'https://example.test/field-http','observedAt'=>'2026-08-28','payload'=>['humanEntered'=>true]]));self::assertSame(201,$res->status(),$res->body());}$deliverable=$k->handle($this->json('POST',"/api/v1/survey-jobs/$id/deliverables",$h,['expectedVersion'=>3,'deliverableType'=>'topographical_plan','title'=>'Topo P01','status'=>'complete','externalReference'=>'TOPO-HTTP','sourceUrl'=>'https://example.test/topo-http','payload'=>['signedOutside'=>true]]));self::assertSame(201,$deliverable->status(),$deliverable->body());$fees=$k->handle($this->json('POST',"/api/v1/survey-jobs/$id/fees",$h,['expectedVersion'=>4,'fieldDays'=>'2.00','fieldDayRateCents'=>150000,'officeDays'=>'1.50','officeDayRateCents'=>120000,'travelDistanceKm'=>'80.00','travelRateCentsPerKm'=>650,'complexityAllowanceCents'=>25000,'statutoryFeeCents'=>45000,'statutorySourceTitle'=>'CSG fees','statutorySourceUrl'=>'https://csg.dlrrd.gov.za/fees.htm','statutorySourceRetrievedAt'=>'2026-08-28']));self::assertSame(200,$fees->status(),$fees->body());self::assertSame(557000,$fees->json()['data']['privateProfessionalFeeCents']);$issue=$k->handle($this->json('POST',"/api/v1/survey-jobs/$id/issue",$h,['expectedVersion'=>5,'humanConfirmed'=>true,'professionalRole'=>'land_surveyor','reason'=>'Exact survey evidence and separated fees reviewed.','externalReference'=>'ISSUE-HTTP-01']));self::assertSame(200,$issue->status(),$issue->body());self::assertFalse($issue->json()['data']['surveyorGeneralApprovalClaimed']);$list=$k->handle(Request::json('GET',"/api/v1/projects/$p/survey-jobs",$h));self::assertSame(200,$list->status());self::assertCount(1,$list->json()['data']);$export=$k->handle(Request::json('GET',"/api/v1/survey-jobs/$id/exports/json",$h));self::assertSame(200,$export->status());self::assertSame(hash('sha256',$export->body()),$export->header('X-Content-Sha256'));}
 private function seed():array{$o=Identifier::generate();$u=Identifier::generate();$reviewer=Identifier::generate();$p=Identifier::generate();$this->pdo->prepare("INSERT INTO users(id,email,password_hash,status,email_verified_at) VALUES(UNHEX(:u),'survey-http@example.test','hash','active',UTC_TIMESTAMP(6)),(UNHEX(:reviewer),'survey-http-reviewer@example.test','hash','active',UTC_TIMESTAMP(6))")->execute(['u'=>$u,'reviewer'=>$reviewer]);$this->pdo->prepare("INSERT INTO organisations(id,name,slug,status) VALUES(UNHEX(:o),'Survey HTTP',:slug,'active')")->execute(['o'=>$o,'slug'=>'survey-http-'.substr($o,0,8)]);$this->pdo->prepare("INSERT INTO organisation_memberships(id,organisation_id,user_id,role,status) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),'owner','active')")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u]);$this->pdo->prepare("INSERT INTO verification_records(id,organisation_id,user_id,kind,grade,registration_body,registration_number,popia_consent_at,processing_purpose,retention_until,reviewed_by,reviewed_at) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:u),'professional_registration','manually_reviewed','SAGC','GPrLS-HTTP',UTC_TIMESTAMP(6),'Survey HTTP test',DATE_ADD(UTC_DATE(),INTERVAL 1 YEAR),UNHEX(:reviewer),UTC_TIMESTAMP(6))")->execute(['id'=>Identifier::generate(),'o'=>$o,'u'=>$u,'reviewer'=>$reviewer]);$this->pdo->prepare("INSERT INTO projects(id,organisation_id,project_code,project_name,client_name,municipality,property_reference,property_use,land_use_notes,lead_professional_role,current_phase,created_by) VALUES(UNHEX(:p),UNHEX(:o),'SUR-HTTP','Survey HTTP','Client','Tshwane','Erf 71','Mixed use','Survey','land_surveyor','feasibility',UNHEX(:u))")->execute(['p'=>$p,'o'=>$o,'u'=>$u]);return[$o,$u,$p];}private function json(string$m,string$p,array$h,array$b):Request{return Request::json($m,$p,$h+['Content-Type'=>'application/json'],json_encode((object)$b,JSON_THROW_ON_ERROR));}
}
